[
  {
    "id": "c001",
    "name": "Paragraph 1 — Amendment of PETROLEUM ARGUS Identification of Goods and Services",
    "text": "1. Petroleum Argus Limited shall amend the identification of goods and services set forth in the application to register PETROLEUM ARGUS (App. No. 75/337,886) to the following: Electronic publications, namely, journals, newsletters, reports, newspapers, pamphlets, periodicals, magazines, and manuals reporting oil pricing worldwide, developments in the oil industry, and related topics such as oil drilling, technology and infrastructure and not including information concerning asset management and investment advice relating to stocks and bonds in electronic format downloadable from and made available via a global computer network on a subscription basis. Printed publications, namely, journals, newsletters, reports, newspapers, pamphlets, periodicals, magazines, and manuals reporting oil pricing, developments in the oil industry, and related topics such as oil drilling, technology and infrastructure and not including information concerning asset management and investment advice relating to stocks and bonds, in Class 16. Financial information services regarding the energy industry in the nature of conveying pricing information about fuel and energy products via a global computer network and not including information concerning asset management and investment advice relating to stocks and bonds, in Class 36."
  },
  {
    "id": "c002",
    "name": "Paragraph 2 — Covenant Not to Oppose PETROLEUM ARGUS Application",
    "text": "2. Argus Research Group, Inc. will not oppose or seek to cancel the trademark application for PETROLEUM ARGUS (SN 75/337,886) owned by Petroleum Argus Ltd. or otherwise contest or challenge Petroleum Argus’ rights in the mark PETROLEUM ARGUS as shown in that application for the goods and services as set forth in that application as amended pursuant to -1- paragraph 1 of this agreement or Petroleum Argus’ ownership thereof and exclusive rights therein or do any act or thing in derogation thereof."
  },
  {
    "id": "c003",
    "name": "Paragraph 3 — Covenant Not to Oppose ENERGY ARGUS & Design Registrations",
    "text": "3. Argus Research Group, Inc. will not oppose or seek to cancel the trademark registration for ENERGY ARGUS & Design (Reg. No. 2,387,568) and ENERGY ARGUS & Design (Reg. No. 2,450,022) owned by Petroleum Argus Ltd. or otherwise contest or challenge Petroleum Argus’ rights in the mark ENERGY ARGUS as shown in the registrations for the goods and services as set forth in the registrations or Petroleum Argus’ ownership thereof and exclusive rights therein or do any act or thing in derogation thereof."
  },
  {
    "id": "c004",
    "name": "4. Governing law",
    "text": "4. This agreement and the performance of shall be governed by and be construed under the laws of the State of New York where the agreement was prepared without recourse to New York’s conflicts of law principles. This provision extends to the United States, its territories and possessions."
  },
  {
    "id": "c005",
    "name": "5. Successors and assigns",
    "text": "5. This agreement is binding upon and inures to the benefit of the parties, their successors, licensees and assigns."
  },
  {
    "id": "c006",
    "name": "Paragraph 6 — Entire Agreement",
    "text": "6. This is the entire agreement and may be modified only in writing signed by both parties."
  },
  {
    "id": "c007",
    "name": "7. Costs and attorneys' fees",
    "text": "7. Both parties will pay all their own costs in attorneys’ fees."
  },
  {
    "id": "c008",
    "name": "8. Confidentiality",
    "text": "8. The parties will agree to keep the terms of this agreement confidential except as required by Court order and/or state and federal rules of civil procedure."
  }
]

